+{"candidate_id":"geometry-global-sinkhorn-poincare-squared","source_sha256":"ff6e4a0bd0dd56ed6799a3baaa1f194a8b4953e5d3fdd41295c136bc63652b21","test_source":"import importlib.util\nimport math\nimport pathlib\nimport unittest\n\nimport torch\n\nSOURCE = pathlib.Path('/fs04/ar57/wenyu/GeneRec/stage2_RQ-VAE/TIGER_c117_global_sinkhorn_poincare/model/hyperbolic.py')\nspec = importlib.util.spec_from_file_location('candidate_hyperbolic', SOURCE)\nhyperbolic = importlib.util.module_from_spec(spec)\nspec.loader.exec_module(hyperbolic)\n\n\nclass TestFrozenPoincareMath(unittest.TestCase):\n    def test_axis_distance_has_independent_closed_form_value(self):\n        # x=0, y=1/2: u=2||x-y||^2/(1-||y||^2)=2/3,\n        # arcosh(5/3)=ln(3), so D_1^2=(ln 3)^2.\n        x = torch.tensor([[0.0]], dtype=torch.float64)\n        y = torch.tensor([[0.5]], dtype=torch.float64)\n        got = hyperbolic.squared_distance(x, y, c=1.0)\n        self.assertAlmostEqual(got.item(), math.log(3.0) ** 2, places=12)\n\n    def test_nonzero_endpoints_numeric_reference(self):\n        # For x=3/10,y=-1/5, u=2*(1/2)^2/((91/100)(24/25));\n        # independently evaluate the defining arcosh expression.\n        x_value, y_value = 0.3, -0.2\n        u = 2.0 * (x_value-y_value)**2 / ((1-x_value**2)*(1-y_value**2))\n        expected = math.log1p(u + math.sqrt(u*(u+2.0)))**2\n        got = hyperbolic.squared_distance(torch.tensor([x_value], dtype=torch.float64),\n                                          torch.tensor([y_value], dtype=torch.float64), c=1.0)\n        self.assertAlmostEqual(got.item(), expected, places=12)\n\n    def test_flat_limit_is_four_times_euclidean_squared_distance(self):\n        x = torch.tensor([[0.2, -0.1], [0.0, 0.5]], dtype=torch.float64)\n        y = torch.tensor([[-0.3, 0.4], [0.1, 0.0]], dtype=torch.float64)\n        expected = torch.tensor([1.70, 1.04], dtype=torch.float64)\n        torch.testing.assert_close(hyperbolic.squared_distance(x, y, c=0.0), expected, rtol=0, atol=1e-14)\n        torch.testing.assert_close(hyperbolic.squared_distance(x, y, c=-2.0), expected, rtol=0, atol=1e-14)\n\n    def test_pairwise_matrix_matches_independent_pairwise_calls(self):\n        x = torch.tensor([[0.0, 0.0], [0.2, -0.1]], dtype=torch.float64)\n        y = torch.tensor([[0.5, 0.0], [-0.2, 0.3], [0.0, 0.4]], dtype=torch.float64)\n        expected = torch.stack([torch.stack([hyperbolic.squared_distance(a, b, c=1.0) for b in y]) for a in x])\n        got = hyperbolic.squared_distance_matrix(x, y, c=1.0)\n        torch.testing.assert_close(got, expected, rtol=1e-12, atol=1e-12)\n        reverse = hyperbolic.squared_distance_matrix(y, x, c=1.0).T\n        torch.testing.assert_close(got, reverse, rtol=1e-12, atol=1e-12)\n\n    def test_projection_uses_closed_radius_ball_and_preserves_interior(self):\n        x = torch.tensor([[0.3, 0.4], [3.0, 4.0], [0.0, 0.0]], dtype=torch.float64)\n        got = hyperbolic.project_ball(x, radius=0.9)\n        torch.testing.assert_close(got[0], x[0], rtol=0, atol=0)\n        torch.testing.assert_close(got[1], torch.tensor([0.54, 0.72], dtype=torch.float64), rtol=0, atol=1e-14)\n        self.assertTrue(torch.all(torch.linalg.vector_norm(got, dim=-1) <= 0.9 + 1e-14).item())\n\n    def test_zero_distance_and_stable_arcosh_at_floor(self):\n        x = torch.tensor([[0.1, -0.2]], dtype=torch.float64)\n        self.assertEqual(hyperbolic.squared_distance(x, x, c=1.0).item(), 0.0)\n        self.assertEqual(hyperbolic.arcosh_stable(torch.tensor([-1.0], dtype=torch.float64)).item(), 0.0)\n        self.assertAlmostEqual(hyperbolic.arcosh_stable(torch.tensor([2.0], dtype=torch.float64)).item(), math.acosh(3.0), places=14)\n\n\nif __name__ == '__main__':\n    unittest.main()\n","falsifiers":["The curved axis case must equal (ln 3)^2 (about 1.20695); a linear or unsquared distance, wrong curvature scaling, or incorrect arcosh argument fails it.","The nonzero-endpoint oracle checks both endpoint denominator factors, guarding against omitted or sign-flipped Poincare terms.","The c=0 and c<0 cases enforce the frozen exact flat limit 4||x-y||^2 rather than a curved fallback or  ||x-y||^2.","Pairwise matrix must agree with independently broadcast scalar-pair calls and be symmetric; a matrix-only distance implementation error fails.","Projection checks the shared fixed radius, radial scaling, and identity for an interior vector.","Coincident points and the arcosh floor must produce zero, detecting an erroneous positive delta floor or unstable negative-excess handling.","This proposal tests only frozen geometry primitives; it does not infer Stage2 or Stage3 outcome metrics, nor call the trainer."]}
*** End Patch"}

